def backfill_legacy_sale_payments(apps, schema_editor):
    using = schema_editor.connection.alias
    Sale = apps.get_model("retail", "Sale")
    Payment = apps.get_model("retail", "Payment")
    PaymentAllocation = apps.get_model("retail", "PaymentAllocation")
    confirmed_status = "confirmed"
    pending_status = "pending"

    for sale in Sale.objects.using(using).filter(
        payment_method__in=["cash", "mpesa"]
    ).iterator():
        payment_status = (
            confirmed_status if sale.status == "posted" else pending_status
        )
        payment = Payment.objects.using(using).create(
            organisation_id=sale.organisation_id,
            purpose="sale",
            method=sale.payment_method,
            status=payment_status,
            sale_id=sale.pk,
            customer_id=sale.customer_id,
            branch_id=sale.branch_id,
            shift_id=sale.shift_id,
            amount=sale.total,
            idempotency_key=uuid.uuid5(
                sale.idempotency_key,
                "legacy-sale-payment",
            ),
            request_fingerprint=sale.request_fingerprint,
            initiated_by_id=sale.cashier_id,
            confirmed_at=(
                sale.completed_at if payment_status == confirmed_status else None
            ),
        )
        PaymentAllocation.objects.using(using).create(
            organisation_id=sale.organisation_id,
            payment_id=payment.pk,
            sale_id=sale.pk,
            amount=sale.total,
        )


